import{C as o}from"./chunks/ChapterNav.IivojZ7p.js";import{Q as u,j as q,m as p,o as e}from"./chunks/framework.DOi4mjdC.js";const s=JSON.parse('{"title":"第五十回 芦雪广争联即景诗 暖香坞雅制春灯谜","description":"","frontmatter":{"title":"第五十回 芦雪广争联即景诗 暖香坞雅制春灯谜"},"headers":[],"relativePath":"books/mingzhu/hongloumeng/ch50.md","filePath":"books/mingzhu/hongloumeng/ch50.md"}'),a={name:"books/mingzhu/hongloumeng/ch50.md"},_=Object.assign(a,{setup(n){return(r,t)=>(u(),q("div",null,[t[0]||(t[0]=p('<h1 id="第五十回-芦雪广争联即景诗-暖香坞雅制春灯谜" tabindex="-1">第五十回 芦雪广争联即景诗 暖香坞雅制春灯谜 <a class="header-anchor" href="#第五十回-芦雪广争联即景诗-暖香坞雅制春灯谜" aria-label="Permalink to &quot;第五十回 芦雪广争联即景诗 暖香坞雅制春灯谜&quot;">​</a></h1><p>话说薛宝钗道：&quot;到底分个次序，让我写出来。&quot;说着，便令众人拈阄为序。起首恰是李氏，然后按次各各开出。凤姐儿说道：&quot;既是这样说，我也说一句在上头。&quot;众人都笑说：&quot;更妙了。&quot;宝钗便将稻香老农之上补了一个&quot;凤&quot;字。李纨又将题目讲与他听。凤姐想了半日，笑道：&quot;你们别笑话我。我只有一句粗话，下剩的我就不知道了。&quot;众人都笑道：&quot;越是粗话越好，你说了，就只管干正事去罢。&quot;凤姐笑道：&quot;我想下雪必刮北风。昨晚听见一夜的北风，我有了一句，就是&#39;一夜北风紧&#39;，可使得？&quot;众人听了，都相视笑道：&quot;这句虽粗，不见底下的，这正是会作诗的起法。不但好，而且留了多少地步与后人。就是这句为首，稻香老农快写上，续下去。&quot;凤姐和李婶平儿又吃了两杯酒，自去了。这里李纨便写了：</p><p>&quot;一夜北风紧，&quot;</p><p>自己联道：</p><p>&quot;开门雪尚飘。入泥怜洁白，&quot;</p><p>香菱道：</p><p>&quot;匝地惜琼瑶。有意荣枯草，&quot;</p><p>探春道：</p><p>&quot;无心饰萎苕。价高村酿熟，&quot;</p><p>李绮道：</p><p>&quot;年稔府粱饶。葭动灰飞管，&quot;</p><p>李纹道：</p><p>&quot;阳回斗转杓。寒山已失翠，&quot;</p><p>岫烟道：</p><p>&quot;冻浦不闻&#39;潮&#39;。易挂疏枝柳，&quot;</p><p>湘云道：</p><p>&quot;难堆破叶蕉。麝煤融宝鼎，&quot;</p><p>宝琴道：</p><p>&quot;绮袖笼金貂。光夺窗前镜，&quot;</p><p>黛玉道：</p><p>&quot;香粘壁上椒。斜风仍故故，&quot;</p><p>宝玉道：</p><p>&quot;清梦转聊聊。何处梅花笛，&quot;</p><p>宝钗道：</p><p>&quot;谁家碧玉箫。鳌愁坤轴陷，&quot;</p><p>李纨笑道：&quot;我替你们看热酒去罢。&quot;宝钗命宝琴续联。只见湘云起来道：</p><p>&quot;龙斗阵云销。野岸回孤棹，&quot;</p><p>宝琴也站起道：</p><p>&quot;&#39;吟&#39;鞭指灞桥。赐裘怜抚戍，&quot;</p><p>湘云那里肯让人，且别人也不如他敏捷，都看他扬眉挺身的说道：</p><p>&quot;加絮念征徭。坳垤审夷险，&quot;</p><p>宝钗连声赞好，也便联道：</p><p>&quot;枝柯怕动摇。皑皑轻趁步，&quot;</p><p>黛玉忙联道：</p><p>&quot;翦翦舞随腰。煮芋成新赏，&quot;</p><p>一面说，一面推宝玉命他联。宝玉正看宝钗、宝琴、黛玉三人共战湘云，十分有趣，那里还顾得联诗。今见黛玉推他，方联道：</p><p>&quot;撒盐是旧谣。苇蓑犹泊钓，&quot;</p><p>湘云笑道：&quot;你快下去。你不中用，倒耽搁了我。&quot;只听得宝琴联道：</p><p>&quot;林斧不闻樵。伏象千峰凸，&quot;</p><p>湘云忙联道：</p><p>&quot;盘蛇一迳遥。花缘经冷聚，&quot;</p><p>宝钗与众人又忙赞好。探春又联道：</p><p>&quot;&#39;色&#39;岂畏霜凋。深院惊寒雀，&quot;</p><p>湘云正渴了，忙忙的吃茶，已被岫烟道：</p><p>&quot;空山泣老鸮。阶墀随上下，&quot;</p><p>湘云忙丢了茶杯，忙联道：</p><p>&quot;池水任浮漂。照耀临清晓，&quot;</p><p>黛玉联道：</p><p>&quot;缤纷入永宵。诚忘三尺冷，&quot;</p><p>湘云忙笑联道：</p><p>&quot;瑞释九重焦。僵卧谁相问，&quot;</p><p>宝琴也忙笑联道：</p><p>&quot;狂游客喜招。天机断缟带，&quot;</p><p>湘云又忙道：</p><p>&quot;海市失鲛绡。&quot;</p><p>林黛玉不容他道出，接着便道：</p><p>&quot;寂寞对台榭，&quot;</p><p>湘云忙联道：</p><p>&quot;清贫怀箪瓢。&quot;</p><p>宝琴也不容情，也忙道：</p><p>&quot;烹茶冰渐沸，&quot;</p><p>湘云见这般自为得趣，又是笑，又忙联道：</p><p>&quot;煮酒叶难烧。&quot;</p><p>黛玉也笑道：</p><p>&quot;没帚山僧扫，&quot;</p><p>宝琴也笑道：</p><p>&quot;埋琴稚子挑。&quot;</p><p>湘云笑的弯了腰，忙念了一句。众人问：&quot;到底说的是什么？&quot;湘云喊道：</p><p>&quot;石楼闲睡鹤，&quot;</p><p>黛玉笑的握着胸口，高声嚷道：</p><p>&quot;锦罽暖亲猫。&quot;</p><p>宝琴也忙笑道：</p><p>&quot;月窟翻银浪，&quot;</p><p>湘云忙联道：</p><p>&quot;霞城隐赤标。&quot;</p><p>黛玉忙笑道：</p><p>&quot;沁梅香可嚼，&quot;</p><p>宝钗笑着称好，也忙联道：</p><p>&quot;淋竹醉堪调。&quot;</p><p>宝琴也忙道：</p><p>&quot;或湿鸳鸯带，&quot;</p><p>湘云忙联道：</p><p>&quot;时凝翡翠翘。&quot;</p><p>黛玉又忙道：</p><p>&quot;无风仍脉脉，&quot;</p><p>宝琴又忙笑联道：</p><p>&quot;不雨亦潇潇。&quot;</p><p>湘云伏着，已笑软了。众人看他三人对抢，也都不顾作诗，看着也只是笑。黛玉还推他往下联，又道：&quot;你也有才尽之时。我听听还有什么舌根嚼了？&quot;湘云只伏在宝钗怀里笑个不住。宝钗推他起来，道：&quot;你有本事把&#39;二萧&#39;的韵全用完了，我才服你。&quot;湘云起身笑道：&quot;我也不是作诗，竟是抢命呢。&quot;众人笑道：&quot;倒是你说罢。&quot;探春早已料定没有自己联的了，便早写出来，因说：&quot;还没收住呢。&quot;李纨听了，接过来便联了一句：</p><p>&quot;欲志今朝乐，&quot;</p><p>李绮收了一句道：</p><p>&quot;凭诗祝舜尧。&quot;</p><p>李纨道：&quot;够了，够了。虽没作完了韵，腾挪的字若生扭，用了倒不好了。&quot;说着，大家来细细评论一回，独湘云的多，都笑道：&quot;这都是那块鹿肉的功劳。&quot;李纨笑道：&quot;逐句评去，都还一气，只是宝玉又落了第了。&quot;宝玉笑道：&quot;我原不会联句，只好担待我罢。&quot;李纨笑道：&quot;也没有社社担待你的。又说韵险了，又整误了，又不会联句了，今日必罚你。我才看见栊翠庵的红梅有趣，我要折一枝来&#39;插&#39;瓶。可厌妙玉为人，我不理他。如今罚你去取一枝来。&quot;众人都道：&quot;这罚的又雅又有趣。&quot;宝玉也乐为，答应着就要走。湘云黛玉一齐说道：&quot;外头冷的很，你且吃杯热酒再去。&quot;湘云早执起壶来，黛玉递了一个大杯，满斟了一杯。湘云笑道：&quot;你吃了我们的酒，你要取不来，加倍罚你。&quot;宝玉忙吃了一杯，冒雪而去。李纨命人好生跟着，黛玉忙拦说：&quot;不必，有了人，反不得了。&quot;李纨点头说是，一面命丫鬟将一个美女耸肩瓶拿来贮了水，准备&#39;插&#39;梅。因又笑道：&quot;回来该咏红梅了。&quot;湘云忙道：&quot;我先作一首。&quot;宝钗忙道：&quot;今儿断乎不容你再作了。你都抢了去，别人都闲着也没趣。回来还罚宝玉。他说不会联句，如今就叫他自己作去。&quot;黛玉笑道：&quot;这话很是。我还有个主意，方才联句不够，莫若拣着联的少的人作红梅。&quot;宝钗笑道：&quot;这话是极。方才邢李三位屈才，且又是客，琴儿和颦儿云儿三个人也抢了许多，我们一概都别作，只让他三个作才是。&quot;李纨因说：&quot;绮儿也不大会作，还是让琴妹作罢。&quot;宝钗只得依允。又道：&quot;就用&#39;红梅花&#39;三个字作韵，每人一首七律。邢大妹作&#39;红&#39;字，你们李大妹作&#39;梅&#39;字，琴儿作&#39;花&#39;字。&quot;李纨道：&quot;饶过宝玉去，我不服。&quot;湘云忙道：&quot;有个好题目命他作。&quot;众人问何题目。湘云道：&quot;命他就作&#39;访妙玉乞红梅&#39;，岂不有趣。&quot;众人听了，都说&quot;有趣&quot;。一语未了，只见宝玉笑掮了一枝红梅进来。众丫鬟忙已接过，&#39;插&#39;入瓶内。众人都笑称谢。宝玉笑道：&quot;你们如今赏顽罢。也不知费了我多少精神呢。&quot;说着，探春早又递过一钟暖酒来。众丫鬟走上来接了蓑笠掸雪。各人房中丫鬟都添送衣服来。袭人也遣人送了半旧的狐腋褂来。李纨命人将那蒸的大芋头盛了一盘，又将朱橘、黄橙、橄榄等物盛了两盘，命人带与袭人去。湘云且告诉宝玉方才的诗题，又催宝玉快作。宝玉道：&quot;好姐姐妹妹，让我自己用韵罢，别限韵了。&quot;众人都说：&quot;随你作去罢。&quot;一面说，一面大家看梅花。原来这枝梅花只有二尺来高，傍有一横枝纵横而出，约有五六尺长，其间小枝分歧，或如蟠螭，或如僵蚓，或孤削如笔，或密聚如林，花吐胭脂，香欺兰蕙，各各称赏。谁知邢岫烟、李纹、薛宝琴三人都已&#39;吟&#39;成，各自写了出来。众人便依&quot;红梅花&quot;三字之序看去，写道是：</p><p>&quot;咏红梅花得红字 邢岫烟</p><p>桃未芳菲杏未红，冲寒先已笑东风。</p><p>魂飞庾岭春难辨，霞隔罗浮梦未通。</p><p>绿萼添妆融宝炬，缟仙扶醉跨残虹。</p><p>看来岂是寻常色，浓淡由他冰雪中。</p><p>咏红梅花得梅字 李 纹</p><p>白梅懒赋赋红梅，逞艳先迎醉眼开。</p><p>冻脸有痕皆是血，酸心无恨亦成灰。</p><p>误吞丹药移真骨，偷下瑶池脱旧胎。</p><p>江北江南春灿烂，寄言蜂蝶漫疑猜。</p><p>咏红梅花得花字 薛宝琴</p><p>疏是枝条艳是花，春妆儿女竞奢华。</p><p>闲庭曲槛无馀雪，流水空山有落霞。</p><p>幽梦冷随红袖笛，游仙香泛绛河槎。</p><p>前身定是瑶台种，无复相疑色相差。&quot;</p><p>众人看了都笑称赏了一回，又指末一首说更好。宝玉见宝琴年纪最小，才又敏捷，深为奇异。黛玉湘云二人斟了一小杯酒，齐贺宝琴。宝钗笑道：&quot;三首各有各好。你们两个天天捉弄厌了我，如今又捉弄他来了。&quot;李纨又问宝玉：&quot;你可有了？&quot;宝玉忙道&quot;我倒有了，才一看见那三首，又吓忘了。等我再想。&quot;湘云听说便拿了一枝铜火箸击着手炉，说道：&quot;我击鼓了。若鼓绝不成，又要罚的。&quot;宝玉笑道：&quot;我已有了。&quot;黛玉提起笔来，说道：&quot;你念，我写。&quot;湘云便击了一下，笑道：&quot;一鼓绝。&quot;宝玉笑道：&quot;有了，你写罢。&quot;众人听他念道：</p><p>&quot;酒未开樽句未裁，&quot;</p><p>黛玉写了，摇头笑道：&quot;起的平平。&quot;湘云又道：&quot;快着。&quot;宝玉笑道：</p><p>&quot;寻春问腊到蓬莱。&quot;</p><p>黛玉湘云都点头笑道：&quot;有些意思了。&quot;宝玉又道：</p><p>&quot;不求大士瓶中露，为乞嫦娥槛外梅。&quot;</p><p>黛玉写了，又摇头说：&quot;凑巧而已。&quot;湘云忙催二鼓。宝玉又笑道：</p><p>&quot;入世冷挑红雪去，离尘香割紫云来。</p><p>槎枒谁惜诗肩瘦，衣上犹沾佛院苔。&quot;</p><p>黛玉写毕，湘云大家才评论时，只见几个丫鬟跑进来回道：&quot;老太太来了。&quot;众人忙迎出来。大家又笑道：&quot;怎么这等高兴。&quot;说着，远远见贾母围了大斗篷，戴着灰鼠暖兜，坐着小竹轿，打着青绸油伞，鸳鸯琥珀等五六个丫鬟，每人都是打着伞，拥轿而来。李纨等忙往上迎，贾母命人止住，说：&quot;只站在那里就是了。&quot;来至跟前，贾母笑道：&quot;我瞒着你太太和凤丫头来了。大雪地下，我坐着这个无妨，没的叫他娘儿们来跴雪。&quot;众人忙一面上前接斗篷，搀扶着，一面答应着。</p><p>贾母来至室中，先笑道：&quot;好俊梅花！你们也会乐，我来着了。&quot;说着，李纨早命人拿了个大狼皮褥子来铺在当中。贾母坐了，因笑道：&quot;你们只管照旧顽笑吃喝。我因为天短了，不敢睡中觉，抹了一会牌，想起你们来了，我也来凑个趣儿。&quot;李纨早又捧过手炉来。探春另拿了一副杯箸来，亲自斟了暖酒，奉与贾母。贾母便饮了一口，问：&quot;那个盘子里是什么东西？&quot;众人忙捧了过来，回说：&quot;是糟鹌鹑。&quot;贾母道：&quot;这倒罢了，撕一两点腿子来。&quot;李纨忙答应了，要水洗手，亲自来撕。贾母又道：&quot;你们仍旧坐下说笑我听。&quot;又命李纨：&quot;你也坐下，就如同我没来的一样才好。不然，我就去了。&quot;</p><p>众人听了，方依次坐下，只李纨便挪到尽下边。贾母因问作何事，众人便说作诗。贾母道：&quot;有作诗的，不如作些灯谜，大家正月里好顽。&quot;众人答应了。说笑了一回。贾母便说：&quot;这里&#39;潮&#39;湿，你们别久坐，仔细受了&#39;潮&#39;湿。&quot;因说：&quot;你四妹妹那里暖和，我们到那里瞧瞧他的画儿，赶年可有了。&quot;众人笑道：&quot;那里能年下就有了！只怕明年端阳有了。&quot;贾母道：&quot;这还了得！他竟比盖这园子还费工夫了。&quot;</p><p>说着，仍坐了竹椅轿，大家围随，过了藕香榭，穿入一条夹道。东西两边皆有过街门。门楼上里外皆嵌着石头匾。如今进的是西门，向外的匾上凿着&quot;穿云&quot;二字，向里的凿着&quot;度月&quot;两字。来至堂中，进了向南的正门，贾母下了轿，惜春已接了出来。从里边游廊过去，便是惜春的卧房，门斗上有&quot;暖香坞&quot;三个字。早有几个人打起猩红毡帘，已觉温香拂脸。大家进入房中，贾母并不归坐，只问：&quot;画在那里？&quot;惜春因笑回：&quot;天气寒冷了，胶&#39;性&#39;皆凝涩不润，画了恐不好看，故此收起来。&quot;贾母笑道：&quot;我年下就要的。你别脱懒儿。快拿出来，给我快画。&quot;</p><p>一语未了，忽见凤姐儿披着紫羯绒褂，笑的来了，口内说道：&quot;老祖宗今儿也不告诉人，私自就来了，要我好找。&quot;贾母见他来了，心中自是喜悦，便道：&quot;我怕你们冷着了，所以不许人告诉你们去。你真个鬼灵精儿，到底找了我来。依理，孝敬也不在这上头。&quot;凤姐笑道：&quot;我那里是孝敬的心找了来。我因为到了老祖宗那里，鸦没雀静的，问小丫头子们，他们又不肯叫我找到园里来。我正疑&#39;惑&#39;，忽然来了两三个姑子，我心里才明白了。那姑子必是来送年疏，或要年例香例银子，老祖宗年下的事也多，一定是躲债来了。如今来回老祖宗，债主已去，不用躲着了。已预备下稀嫩的野鸡，请用晚饭去，再迟一回就老了。&quot;他一行说，众人一行笑。</p><p>凤姐儿也不等贾母说话，便命人抬过轿子来。贾母笑着，搀了凤姐的手，仍旧上轿，带着众人，说笑出了夹道东门。一看四面粉装银砌，忽见宝琴披着凫靥裘，站在山坡上遥等，身后一个丫鬟，抱着一瓶红梅。众人都笑道：&quot;少了两个人，他却在这里等着，也弄梅花去了。&quot;贾母喜的忙笑道：&quot;你们瞧这山坡上配上他的这个人品又是这件衣裳，后头又是这梅花，像个什么？&quot;众人都笑道：&quot;就像老太太屋里挂的仇十洲画的艳雪图。&quot;贾母摇头笑道：&quot;那画的那里有这件衣裳，人也不能这样好。&quot;</p><p>一语未了，只见宝琴背后转出一个披大红猩毡的人来。贾母道：&quot;那又是那个女孩儿？&quot;众人笑道：&quot;我们都在这里，那是宝玉。&quot;贾母笑道：&quot;我的眼越发花了。&quot;说话之间，来至跟前，可不是宝玉和宝琴。宝玉笑向宝钗黛玉等道：&quot;我才又到了栊翠庵，妙玉每人送你们一枝梅花，我已经打发人送去了。&quot;众人都笑说：&quot;多谢你费心。&quot;</p><p>说话之间，已出了园门，来至贾母房中。吃毕饭，大家又说笑了一回。忽见薛姨妈也来了，说：&quot;好大雪，一日也没过来望候老太太。今日老太太倒不高兴？正该赏雪才是。&quot;贾母笑道：&quot;何曾不高兴，我找了他们姊妹们去顽了一会子。&quot;薛姨妈笑道：&quot;昨儿晚上，我原想着今儿要和我们姨太太借一日园子，摆两桌粗酒，请老太太赏雪的。又见老太太安息的早。我闻得女儿说，老太太心下不大爽，因此今日也没敢惊动。早知如此，我正该请。&quot;贾母笑道：&quot;这才是十月里头场雪，往后下雪的日子多呢，再破费不迟。&quot;薛姨妈笑道：&quot;果然如此，算我的孝心虔了。&quot;</p><p>凤姐笑道：&quot;姑妈仔细忘了。如今先秤了五十两银子来，交给我收着，一下雪，我就预备下酒了。姑妈也不用&#39;操&#39;心，也不得忘了。&quot;贾母笑道：&quot;既这么说，姨太太给他五十两银子收着，我和他每人分二十五两。到下雪的日子，我装心里不快，混过去了。姨太太更不用&#39;操&#39;心，我和凤丫头倒得了实惠。&quot;凤姐将手一拍，笑道：&quot;妙极了。这和我的主意一样。&quot;众人都笑了。贾母笑道：&quot;呸，没脸的！就顺着竿子爬上来了。你不该说姨太太是客，在咱们家受屈，我们该请姨太太才是，那里有破费姨太太的理！不这样说呢，还有脸先要五十两银子，真不害臊。&quot;凤姐笑道：&quot;我们老祖宗最是有眼&#39;色&#39;的，试一试，姑妈若松呢，拿出五十两来，就和我分；这会子估量着不中用了，翻过脸来拿我做法子，说出这些大方话来。如今我也不和姑妈要银子，竟替姑妈出银子治了酒，请老祖宗吃了，我另外再封五十两银子孝敬老祖宗，算是罚我包揽闲事，这可好不好？&quot;话未说完，众人已笑倒在炕上。</p><p>贾母因又说及宝琴雪下折梅比画儿上还好，因又细问他的年庚八字并家内景况。薛姨妈度其意思，大约要与宝玉求配。薛姨妈心中固也遂意，只是已许过梅家了，因贾母尚未明说，自己也不好拟定，遂半吐半&#39;露&#39;告诉贾母道：&quot;可惜这孩子没福，前年他父亲就没了。他从小儿见的世面倒多，跟他父母四山五岳都走遍了。他父亲是好乐的，各处因有买卖，带着家眷，这一省逛一年，明年又往那一省逛半年，所以天下十停走了有五六停了。那年在这里，把他许了梅翰林的儿子，偏第二年他父亲就辞世了。如今他母亲又是痰症。&quot;凤姐也不等说完，便嗐声跺脚的说：&quot;偏不巧！我正要作个媒呢，又已经许了人家。&quot;贾母笑道：&quot;你要给谁说媒？&quot;凤姐说道：&quot;老祖宗别管，我心里看准了他们两个是一对。如今已许了人家，说也无益，不如不说罢了。&quot;贾母也知凤姐之意，听见有了人家，也就不提了。大家又闲话了一会方散。一宿无话。</p><p>次日雪晴，饭后，贾母又亲嘱惜春：&quot;不管冷暖，你只画去。赶到年下，十分不能便罢了。第一要紧，把昨日琴儿和丫头梅花，照模照样，一笔别错，快快添上。&quot;惜春听了，虽是为难，只得应了。一时众人都来看他如何画。惜春只是出神。</p><p>李纨因笑向众人道：&quot;让他自己想去，咱们且说话儿。昨儿老太太只叫作灯谜儿，回家和绮儿纹儿睡不着，我就编了两个四书的。他两个每人也编了两个。&quot;众人听了都笑道：&quot;这倒该作的。先说了，我们猜猜。&quot;李纨笑道：&quot;&#39;观音未有世家传&#39;，打四书一句。&quot;湘云接着就说：&quot;&#39;在止于至善&#39;。&quot;宝钗笑道：&quot;你也想一想&#39;世家传&#39;三个字的意思再猜。&quot;李纨笑道：&quot;再想。&quot;黛玉笑道：&quot;哦，是了，是&#39;虽善无徵&#39;。&quot;众人都笑道：&quot;这句是了。&quot;李纨又道：&quot;&#39;一池青草草何名&#39;。&quot;湘云又忙道：&quot;这一定是&#39;蒲芦也&#39;。再不是不成？&quot;李纨笑道：&quot;这难为你猜。纹儿的是&#39;水向石边流出冷&#39;，打一古人名。&quot;探春笑问道：&quot;可是山涛？&quot;李纹笑道：&quot;是。&quot;李纨又道：&quot;绮儿的是个&#39;萤&#39;字，打一个字。&quot;众人猜了半日。宝琴笑道：&quot;这个意思却深，不知可是花草的&#39;花&#39;字？&quot;李绮笑道：&quot;恰是了。&quot;众人道：&quot;萤与花何干？&quot;黛玉笑道：&quot;妙的很！萤可不是草化的。&quot;众人会意，都笑了说&quot;好&quot;。</p><p>宝钗道：&quot;这些虽好，不合老太太的意思，不如作些浅近的物儿，大家雅俗共赏才好。&quot;众人都道：&quot;也要作些浅近的俗物才是。&quot;湘云想了一想，笑道：&quot;我编了一支&#39;点绛唇&#39;，却真是个俗物，你们猜猜。&quot;说着，便念道：</p><p>&quot;溪壑分离，红尘游戏，真何趣，名利犹虚，后事终难继。&quot;</p><p>众人都不解，想了半日，也有猜是和尚的，也有猜是道士的，也有猜是偶戏人的。宝玉笑了半日，道：&quot;都不是。我猜着了，一定是耍的猴儿。&quot;湘云笑道：&quot;这个正是了。&quot;众人道：&quot;前头都好，末后一句怎么解？&quot;湘云道：&quot;那一个耍的猴儿，不是剁了尾巴去的。&quot;众人听了，都笑起来，说：&quot;偏他编个谜儿也是刁钻古怪的。&quot;李纨道：&quot;昨儿姨妈说，琴妹见的世面多，走的道路也多，你正该编谜儿，正用着了。你的诗又好，何不编几个我们猜一猜？&quot;宝琴听了，点头含笑，自去寻思。宝钗也有了一个，念道：</p><p>&quot;镂檀锲梓一层层，岂系良工堆砌成。</p><p>虽是半天风雨过，何曾闻得梵铃声。</p><p>——打一物</p><p>众人猜时，宝玉也有了一个，念道：</p><p>&quot;天上人间两渺茫，琅玕节过谨提防。</p><p>鸾音鹤信须凝睇，好把欷歔答上苍。&quot;</p><p>黛玉也有了一个，念道是：</p><p>&quot;騄駬何劳缚紫绳，驰城逐堑见狰狞。</p><p>主人指示风雷动，鳌背三山独立名。&quot;</p><p>探春也有了一个，方欲念时，宝琴走过来笑道：&quot;我从小儿所走的地方古迹不少，我如今拣了十个地方的古迹，作了十首怀古的诗。诗虽粗鄙，却怀往事，又暗隐俗物十件。姐姐们请猜一猜。&quot;众人听了，都说：&quot;这倒巧。何不写出来大家一看。&quot;要知端的，下回分解。</p>',141)),e(o,{"prev-link":"./ch49","prev-text":"第49回","next-link":"./ch51","next-text":"第51回","toc-link":"../hongloumeng"})]))}});export{s as __pageData,_ as default};
